    if type(data) is not dict:
        raise Invalid()
    if set(data.keys()) != TOP_KEYS:
        raise Invalid()
    if not is_int(data["version"]) or data["version"] != 1:
        raise Invalid()

    ixps_raw = data["ixps"]
    if type(ixps_raw) is not list or len(ixps_raw) > 1024:
